let table = {{workflowparams:data}};

if({{workflowparams:data.pr_no_type}} !== -9999 && (
  !{{workflowparams:data.pr_no}} || {{workflowparams:data.pr_no}} === null || {{workflowparams:data.pr_no}} === ''
)) {
  table.pr_no = 'draft'
}

return {table};

const table = {{node:code_node_9XHFDoiG.data.table}}
return {
  required_fields: JSON.stringify([
  { name: "plant_id", label: "Plant ID" },
  { name: "pr_no", label: "Requisition Number" },
  {
