let table = {{workflowparams:data}};

if (
  {{workflowparams:data.pr_no_type}} !== -9999 &&
  (!{{workflowparams:data.pr_no}} ||
    {{workflowparams:data.pr_no}} === null ||
    {{workflowparams:data.pr_no}} === "" ||
    {{workflowparams:data.previous_status}} !== "Issued")
) {
  table.pr_no = 'issued'
}

return {table};

const table = {{node:code_node_3RAiFbOX.data.table}};
return {
  required_fields: JSON.stringify([
  { name: "plant_id", label: "Plant ID" },
  { name: "pr_no", label: "Requisition Number" },
  { name: "supplier_type", label: "Supplier Type" },
  {
    name: "table_pr",
    label: "Item Information",
    isArray: true,
    arrayType: "object",
    arrayFields: [],
  },
]),
  data: JSON.stringify({
    plant_id: table.plant_id,
    pr_no: table.pr_no,
    supplier_type: table.supplier_type,
    table_pr: table.table_pr
  })
}

const rows =
  {{workflowparams:data.table_pr}} || [];

const flattenRows = (rows) =>
  (Array.isArray(rows) ? rows : []).flatMap(row => {
    const { children, ...currentRow } = row;

    return [
      currentRow,
      ...flattenRows(children),
    ];
  });

return {
  lineItem: JSON.stringify(flattenRows(rows)),
  itemFields:
    "pr_line_material_id,pr_line_material_name,pr_line_material_desc",
  quantityFields: "pr_line_qty"
};

let table = {{workflowparams:data}};

let table_pr = table.table_pr.filter(item => (item.pr_line_material_id || item.pr_line_material_desc || item.pr_line_material_name) && item.pr_line_qty > 0)

table.table_pr = table_pr;

return {table};

let preqData = {{node:code_node_PBv00pLE.data.table}};

// Filter unnecessary line reads the raw params, so it does not carry the
// 'issued' marker that Check Doc No put on pr_no. Approval keys off it.
preqData.pr_no = {{node:code_node_3RAiFbOX.data.table.pr_no}};

// Parents numbered 1, 2, …; children 1/1, 1/2, … (same as Fillback's line_index)
const items = [];
(preqData.table_pr || []).forEach((item, index) => {
  items.push({ ...item, lineNo: `${index + 1}` });
  (Array.isArray(item.children) ? item.children : []).forEach((child, childIndex) => {
    items.push({ ...child, lineNo: `${index + 1}/${childIndex + 1}` });
  });
});

// 0 / empty = no limit, same rule as preq_validation_unitPrice.js
const limitOf = (value) => {
  const n = parseFloat(value);
  return value == null || value === "" || Number.isNaN(n) || n === 0 ? null : n;
};

const minFailed = items.filter((item) => {
  const minPrice = limitOf(item.pr_min_price);
  return minPrice !== null && (parseFloat(item.pr_line_unit_price) || 0) < minPrice;
});

const maxFailed = items.filter((item) => {
  const maxPrice = limitOf(item.pr_max_price);
  return maxPrice !== null && (parseFloat(item.pr_line_unit_price) || 0) > maxPrice;
});

preqData.min_price_result = minFailed.length > 0 ? "failed" : "passed";
preqData.max_price_result = maxFailed.length > 0 ? "failed" : "passed";

const messages = [
  ...minFailed.map(
    (item) => `Line ${item.lineNo}: Unit Price ${item.pr_line_unit_price} is below Min Price ${item.pr_min_price}`,
  ),
  ...maxFailed.map(
    (item) => `Line ${item.lineNo}: Unit Price ${item.pr_line_unit_price} exceeds Max Price ${item.pr_max_price}`,
  ),
];

return { preqData, message: messages.join("<br>") };

let updatedLineItem = [];
let supplierName = "";
// Draft: raw params + draft marker. Issued: filtered lines + issued marker, or,
// when approval is needed, the copy CHECK_APPROVAL handed back (it may have been
// knocked back to Draft, and carries approval_condition).
let data = {{workflowparams:data.preq_status}} == 'Draft'
  ? {{node:code_node_9XHFDoiG.data.table}}
  : {{node:workflow_node_XdoKYWp4.data.needApproval}} == 'Yes'
    ? {{node:workflow_node_XdoKYWp4.data.data}}
    : {{node:code_node_Q9w8GLRZ.data.preqData}};
const tablePR = data.table_pr;

if (data.supplier_type === "Existing Supplier") {
  supplierName = {{node:get_node_69b15XPj.data.data.supplier_com_name}}
} else {
  supplierName = {{node:code_node_yfJBazmc.data.supplier_name}}
}

// Header fields shared by every line, parent and child alike
const commonFields = {
  supplier_id: data.pr_supplier_name || null,
  plant_id: data.plant_id || null,
  payment_term_id: data.pr_payment_term_id || null,
  shipping_preference_id: data.pr_ship_preference_id || null,
  billing_state_id: data.billing_address_state || null,
  billing_country_id: data.billing_address_country || null,
  shipping_state_id: data.shipping_address_state || null,
  shipping_country_id: data.shipping_address_country || null,
  supplier_name: supplierName,
  organization_id: data.organization_id,
  preq_created_by: {{global:nickname}},
  line_status: data.preq_status,
};

const round8 = (value) => Math.round((parseFloat(value) || 0) * 100000000) / 100000000;

const formatNumbers = (preqLineItem) => ({
  // Copy all existing properties
  ...preqLineItem,

  // Round qty and price fields to 8 decimal places
  pr_line_qty: round8(preqLineItem.pr_line_qty),
  pr_line_unit_price: round8(preqLineItem.pr_line_unit_price),
  pr_line_gross: round8(preqLineItem.pr_line_gross),
  order_qty: round8(preqLineItem.order_qty),
  pr_line_discount: round8(preqLineItem.pr_line_discount),
  pr_line_discount_amount: round8(preqLineItem.pr_line_discount_amount),
  pr_line_tax_fee_amount: round8(preqLineItem.pr_line_tax_fee_amount),
  pr_line_amount: round8(preqLineItem.pr_line_amount),

  pr_delivery_date: preqLineItem.pr_delivery_date ?? data.pr_delivery_date
});

for (const [index, preqLineItem] of tablePR.entries()) {
  const formattedItem = {
    ...formatNumbers(preqLineItem),
    ...commonFields,
    line_index: index + 1,

    // If got child, give it the same formatting and header fields
    ...(Array.isArray(preqLineItem.children) && {
      children: preqLineItem.children.map((child, childIndex) => ({
        ...formatNumbers(child),
        ...commonFields,
        line_index: `${index + 1}/${childIndex + 1}`,
      })),
    }),
  };

  updatedLineItem.push(formattedItem);
}

data.table_pr = updatedLineItem;
return {data};

// Custom fields this edit would blank: the payload left the header object, or a line's, out
const missing = (v) => v === undefined || v === null;
const flat = (rows) => {
  const out = [];
  for (const r of Array.isArray(rows) ? rows : []) {
    if (!r || typeof r !== "object") continue;
    out.push(r);
    for (const c of Array.isArray(r.children) ? r.children : []) if (c && typeof c === "object") out.push(c);
  }
  return out;
};
const cf = [{{node:code_node_UFKMCLkT.data.data.custom_fields_8k2wxzce}}][0];
const lines = [{{node:code_node_UFKMCLkT.data.data.table_pr}}][0];
const rawId = [{{workflowparams:data.id}}][0];
const id = missing(rawId) ? "" : String(rawId).trim();
const lineKeys = ["custom_fields_v2a8l69e"];
const lineMiss = flat(lines).some((r) => lineKeys.some((k) => missing(r[k])));
return { need: /^[0-9]{1,20}$/.test(id) && (missing(cf) || lineMiss) ? "YES" : "NO", id: id };

// The stored custom fields for what this edit left out: the header as stored; each line by its id
const missing = (v) => v === undefined || v === null;
const flat = (rows) => {
  const out = [];
  for (const r of Array.isArray(rows) ? rows : []) {
    if (!r || typeof r !== "object") continue;
    out.push(r);
    for (const c of Array.isArray(r.children) ? r.children : []) if (c && typeof c === "object") out.push(c);
  }
  return out;
};
const cf = [{{node:code_node_UFKMCLkT.data.data.custom_fields_8k2wxzce}}][0];
const lines = [{{node:code_node_UFKMCLkT.data.data.table_pr}}][0];
const got = [{{node:get_node_CfStored1.data.data}}][0];
const stored = (Array.isArray(got) ? got[0] : got) || {};
const natKey = null;
const storedRows = flat(stored["table_pr"]);
const sentIds = new Set(flat(lines).map((r) => (missing(r.id) ? "" : String(r.id))).filter((x) => x));
const byId = new Map(storedRows.filter((r) => !missing(r.id) && r.id !== "").map((r) => [String(r.id), r]));
const byKey = new Map();
if (natKey) {
  for (const r of storedRows) {
    if (sentIds.has(String(r.id))) continue;
    const k = missing(r[natKey]) ? "" : String(r[natKey]);
    if (!k) continue;
    if (!byKey.has(k)) byKey.set(k, []);
    byKey.get(k).push(r);
  }
}
const fill = (row) => {
  if (!row || typeof row !== "object") return row;
  let src = !missing(row.id) && row.id !== "" ? byId.get(String(row.id)) : undefined;
  if (!src && natKey) {
    const queue = byKey.get(missing(row[natKey]) ? "" : String(row[natKey]));
    if (queue && queue.length) src = queue.shift();
  }
  const add = {};
  if (src) for (const k of Object.keys(src)) if (k.indexOf("custom_fields") === 0 && missing(row[k]) && !missing(src[k])) add[k] = src[k];
  let next = Object.keys(add).length ? Object.assign({}, row, add) : row;
  if (Array.isArray(row.children)) next = Object.assign({}, next, { children: row.children.map(fill) });
  return next;
};
return { ok: "YES", cf: missing(cf) ? (missing(stored["custom_fields_8k2wxzce"]) ? null : stored["custom_fields_8k2wxzce"]) : cf, lines: Array.isArray(lines) ? lines.map(fill) : lines };

// What the update writes: the payload's custom fields, or the stored ones where this edit left them out
const filled = [{{node:code_node_CfFill1.data}}][0];
if (filled && filled.ok === "YES") return { cf: filled.cf, lines: filled.lines };
const cf = [{{node:code_node_UFKMCLkT.data.data.custom_fields_8k2wxzce}}][0];
return { cf: cf === undefined ? null : cf, lines: [{{node:code_node_UFKMCLkT.data.data.table_pr}}][0] };

let latestPREQData = {{node:code_node_ntvf5pq2.data.preqData}};

// Held back as a draft for approval -> number it now. 'issued' is the same marker
// Check Doc No uses; manual numbering (-9999) keeps the typed number.
if (
  latestPREQData.pr_no_type !== -9999 &&
  (latestPREQData.previous_status === "Draft" || !latestPREQData.previous_status) &&
  latestPREQData.preq_status !== "Issued"
) {
  latestPREQData.pr_no = "issued";
}
latestPREQData.preq_status = "Issued";

// Lines were saved with the header's Draft status. The list page's Convert PO
// only picks up Issued lines, so issue them with the header.
const issueLine = (line) => ({
  ...line,
  line_status: !line.line_status || line.line_status === "Draft" ? "Issued" : line.line_status,
});

latestPREQData.table_pr = (latestPREQData.table_pr || []).map((line) => ({
  ...issueLine(line),
  ...(Array.isArray(line.children) && { children: line.children.map(issueLine) }),
}));

return { latestPREQData };

const lineItem = {{node:code_node_UFKMCLkT.data.data.table_pr}};

const uniqueItemIDs = [
  ...new Set(lineItem.filter((item) => item.pr_line_material_id).map((item) => item.pr_line_material_id))
];

return {
  itemIDs: uniqueItemIDs
}
